#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>

volatile sig_atomic_t recu = 0;

void traiter(int sig) {
    (void) sig;
    recu = 1;
}

int main(void) {
    signal(SIGUSR1, traiter);

    sigset_t bloc;
    sigemptyset(&bloc);
    sigaddset(&bloc, SIGUSR1);
    sigprocmask(SIG_BLOCK, &bloc, NULL);

    raise(SIGUSR1);

    sigset_t pendants;
    sigpending(&pendants);
    if (sigismember(&pendants, SIGUSR1)) {
        printf("SIGUSR1 pendant : oui\n");
    } else {
        printf("SIGUSR1 pendant : non\n");
    }
    printf("avant deblocage, recu = %d\n", (int) recu);

    sigprocmask(SIG_UNBLOCK, &bloc, NULL);
    printf("apres deblocage, recu = %d\n", (int) recu);
    return 0;
}

