    if (pid == -1) { perror("fork"); exit(EXIT_FAILURE); }

    if (pid == 0) {
        close(fd[1]);
        char buff[128];
        ssize_t n = read(fd[0], buff, sizeof(buff) - 1);
        if (n > 0) {
            buff[n] = '\0';
            printf("fils a recu : %s\n", buff);
        }
        close(fd[0]);
        exit(EXIT_SUCCESS);
    }

    close(fd[0]);
    const char *msg = "bonjour";
    write(fd[1], msg, strlen(msg));
    close(fd[1]);
    wait(NULL);
    return 0;
}

