#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>

int main(void) {
    int fd[2];
    if (pipe(fd) == -1) { perror("pipe"); exit(EXIT_FAILURE); }

    pid_t pid = fork();
    if (pid == -1) { perror("fork"); exit(EXIT_FAILURE); }

    if (pid == 0) {
        close(fd[1]);
        dup2(fd[0], 0);
        close(fd[0]);
        int lignes = 0;
        int c;
        while ((c = getchar()) != EOF) {
            if (c == '\n')
                lignes++;
        }
        printf("lignes : %d\n", lignes);
        exit(EXIT_SUCCESS);
    }

    close(fd[0]);
    const char *texte = "rouge\nvert\nbleu\njaune\n";
    write(fd[1], texte, strlen(texte));
    close(fd[1]);
    wait(NULL);
    return 0;
}
